def clamped(image, width, height, x, y):
    x = min(max(x, 0), width - 1)
    y = min(max(y, 0), height - 1)
    return image[y * width + x]


def box_sum(image, width, height, window):
    radius = window // 2
    padded_width = width + 2 * radius
    padded_height = height + 2 * radius
    integral = [[0] * (padded_width + 1) for _ in range(padded_height + 1)]
    for y in range(padded_height):
        row_sum = 0
        for x in range(padded_width):
            row_sum += clamped(image, width, height, x - radius, y - radius)
            integral[y + 1][x + 1] = integral[y][x + 1] + row_sum
    result = []
    for y in range(height):
        for x in range(width):
            result.append(integral[y + window][x + window]
                          - integral[y][x + window]
                          - integral[y + window][x] + integral[y][x])
    return result


def census(image, width, height):
    result = []
    for y in range(height):
        for x in range(width):
            code = 0
            center = image[y * width + x]
            for dy in range(-2, 3):
                for dx in range(-2, 3):
                    if dx == 0 and dy == 0:
                        continue
                    lower = clamped(image, width, height, x + dx, y + dy) < center
                    code = (code << 1) | int(lower)
            result.append(code)
    return result


def texture(image, width, height, window):
    gradient = [
        abs(clamped(image, width, height, x + 1, y)
            - clamped(image, width, height, x - 1, y))
        for y in range(height) for x in range(width)
    ]
    return box_sum(gradient, width, height, window)


def cost_volume(left, right, census_left, census_right, width, height,
                kind, window, disparity_min, disparity_max):
    volume = [[] for _ in left]
    for disparity in range(disparity_min, disparity_max + 1):
        pixels = []
        for y in range(height):
            for x in range(width):
                p = y * width + x
                q = y * width + max(x - disparity, 0)
                if kind == "census":
                    value = (census_left[p] ^ census_right[q]).bit_count()
                else:
                    difference = left[p] - right[q]
                    value = abs(difference) if kind == "sad" else difference * difference
                pixels.append(value)
        totals = box_sum(pixels, width, height, window)
        for row, value in zip(volume, totals):
            row.append(value)
    return volume

from math import gcd

from refinement import two_decimals


REGION_ORDER = ("nonocc", "all", "disc")


def truth_regions(truth, width, height):
    known = [p for p, value in enumerate(truth) if value != 0]
    occluded = []
    for p in known:
        y, x = divmod(p, width)
        g = truth[p]
        target = x - g
        if target < 0 or any(
                truth[y * width + x2] > g
                and x2 - truth[y * width + x2] == target
                for x2 in range(width)):
            occluded.append(p)
    hidden = set(occluded)
    visible = [p for p in known if p not in hidden]
    discontinuities = []
    for p in visible:
        y, x = divmod(p, width)
        adjacent = [
            yy * width + xx
            for yy in range(max(0, y - 1), min(height, y + 2))
            for xx in range(max(0, x - 1), min(width, x + 2))
            if xx != x or yy != y
        ]
        if any(truth[q] != 0 and abs(truth[q] - truth[p]) >= 2 for q in adjacent):
            discontinuities.append(p)
    return {"all": known, "nonocc": visible, "disc": discontinuities,
            "occluded": occluded}


def evaluate(disparities, truth, region):
    errors = [abs(disparities[p] - truth[p]) for p in region if disparities[p]]
    valid = len(errors)
    missing = len(region) - valid
    error_sum = sum(errors)
    return {"pixels": len(region), "valid": valid,
            "bad1": missing + sum(error > 1 for error in errors),
            "bad2": missing + sum(error > 2 for error in errors),
            "error_sum": error_sum,
            "mae": two_decimals(error_sum, valid) if valid else "-",
            "exact": errors.count(0)}


def ratio(numerator, denominator):
    if denominator == 0:
        return "0/1 0.00"
    divisor = gcd(numerator, denominator)
    return (f"{numerator // divisor}/{denominator // divisor} "
            + two_decimals(100 * numerator, denominator))

from pathlib import Path


def read_pgm(path):
    lines = Path(path).read_text(encoding="ascii").splitlines()
    width, height = map(int, lines[1].split())
    values = [int(value) for line in lines[3:] for value in line.split()]
    return width, height, values


def read_parameters(path="input/params.txt"):
    parameters = {}
    samples = []
    text_keys = {"wta_cost", "sgm_cost"}
    list_keys = {"sad_windows", "ssd_windows", "census_windows"}
    for line in Path(path).read_text(encoding="ascii").splitlines():
        key, *values = line.split()
        if key == "sample":
            samples.append(tuple(map(int, values)))
        elif key in text_keys:
            parameters[key] = values[0]
        elif key in list_keys:
            parameters[key] = list(map(int, values))
        else:
            parameters[key] = int(values[0])
    parameters["sample_pixels"] = samples
    return parameters


def write_pgm(path, width, height, pixels):
    lines = ["P2", f"{width} {height}", "255"]
    for y in range(height):
        lines.append(" ".join(map(str, pixels[y * width:(y + 1) * width])))
    Path(path).write_text("\n".join(lines) + "\n", encoding="ascii")

def hundredths(value):
    return f"{value // 100}.{value % 100:02d}"


def two_decimals(numerator, denominator=1):
    rounded = (200 * numerator + denominator) // (2 * denominator)
    return hundredths(rounded)


def depth_hundredths(disparity, focal, baseline):
    return (200 * focal * baseline + disparity) // (2 * disparity)


def subpixel(disparity, costs, disparity_min, disparity_max, focal, baseline):
    index = disparity - disparity_min
    a, b = 0, 1
    if (disparity_min < disparity < disparity_max
            and costs[index - 1] > costs[index]
            and costs[index + 1] >= costs[index]):
        a = costs[index - 1] - costs[index + 1]
        b = 2 * (costs[index - 1] - 2 * costs[index] + costs[index + 1])
    rounded = (200 * (disparity * b + a) + b) // (2 * b)
    return hundredths(rounded), two_decimals(100 * focal * baseline, rounded)
